class Solution {
public:
    int minSteps(string s, string t) {
        int count[26] = {0};
        // Storing the difference of frequencies of characters in t and s.
        for (int i = 0; i < s.size(); i++) {
            count[t[i] - 'a']++;
            count[s[i] - 'a']--;
        }

        int ans = 0;
        // Adding the difference where string t has more instances than s.
        // Ignoring where t has fewer instances as they are redundant and
        // can be covered by the first case.
        for (int i = 0; i < 26; i++) {
            ans += max(0, count[i]);
        }

        return ans;
    }
};

//Editorial: Just using hashing we can find how many characters to be replaced.
class Solution {
public:
    int minSteps(string s, string t) {
        vector<int> freq(26,0);
        for(auto it:s)
            freq[it-'a']+=1;
        for(auto ch:t)
            freq[ch-'a']-=1;
        int ans=0;
        for(auto it:freq)
        {
            if(it<0)
                ans+=it;
        }
        return abs(ans);
    }
};
